function fail(message) { throw new Error('Validation stopped: ' + message); }
function obj(x) { return x !== null && typeof x === 'object' && !Array.isArray(x); }
function parse(x, label = 'JSON') {
  if (typeof x === 'string') {
    let s = x.trim();
    const fence = s.match(/^```(?:json)?\s*\n([\s\S]*?)\n```$/i);
    if (fence) s = fence[1].trim();
    try { x = JSON.parse(s); } catch { fail(label + ' is not complete valid JSON'); }
  }
  if (!obj(x)) fail(label + ' must be an object');
  return x;
}
function arr(x, label) { if (!Array.isArray(x)) fail(label + ' must be an array'); return x; }
function str(x, label) { if (typeof x !== 'string' || !x.trim()) fail(label + ' must be a nonempty string'); return x; }
function strings(x, label) { return arr(x, label).map(v => str(v, label)); }
function norm(s) { return String(s).normalize('NFKC').replace(/\s+/g, ' ').trim(); }
function url(s) { return typeof s === 'string' && /^https?:\/\/[^\s<>"'`]+$/i.test(s); }
function numeric(s) {
  if (typeof s !== 'string' || !/^[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?%?$/.test(s.trim())) return null;
  const n = Number(s.trim().replace(/,/g, '').replace(/%$/, ''));
  return Number.isFinite(n) ? n : null;
}
function hasNumber(text, token) {
  const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^\\d.,])' + escaped + '(?!\\d|[.,]\\d)').test(text);
}
// Accept only known serialization wrappers; never extract a JSON substring from prose.
function unwrap(x, depth = 0) {
  if (depth > 10) fail('tool result wrapper too deep');
  if (typeof x === 'string') { try { return unwrap(JSON.parse(x), depth + 1); } catch (e) { fail('tool result is not valid JSON'); } }
  if (Array.isArray(x)) { if (x.length !== 1) fail('expected one tool result item'); return unwrap(x[0], depth + 1); }
  if (!obj(x)) fail('invalid tool observation');
  if (obj(x.json)) return unwrap(x.json, depth + 1);
  if (Array.isArray(x.response)) return unwrap(x.response, depth + 1);
  if (Array.isArray(x.content) && x.content.length === 1 && x.content[0].type === 'text') return unwrap(x.content[0].text, depth + 1);
  return x;
}
function trace(item, tool) { return arr(item.intermediateSteps, 'intermediateSteps').filter(s => s.action?.tool === tool); }
function md(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\\`*_{}\[\]|]/g, '\\$&').replace(/\r?\n/g, ' '); }
function mdurl(s) { if (!url(s)) fail('invalid citation URL'); return s.replace(/\(/g, '%28').replace(/\)/g, '%29'); }

const item=$input.first().json;
const steps=arr(item.intermediateSteps,'Orchestrator intermediateSteps');
const expected=['Researcher','Analyst','Report_writer'];
const specialist=steps.filter(s=>expected.includes(s.action?.tool));
if(specialist.length!==3 || specialist.some((s,i)=>s.action.tool!==expected[i])) fail('expected one completed Researcher → Analyst → Report_writer sequence; publication blocked');
const [research,analysis,writer]=specialist.map(s=>unwrap(s.observation));
str(research.research_evidence,'research_evidence');str(analysis.analysis_result,'analysis_result');str(writer.report_html,'report_html');
if(analysis.research_evidence_input!==research.research_evidence) fail('evidence changed during Orchestrator handoff');
if(writer.analysis_result_input!==analysis.analysis_result || writer.chart_url_input!==analysis.chart_url) fail('analysis/chart changed during Orchestrator handoff');
const question=$('When chat message received').first().json.chatInput;
if(parse(research.research_evidence).question!==question) fail('research question differs from chat input');
const html=writer.report_html;
if(!/^\s*<!doctype html>/i.test(html) || !/<html\b/i.test(html) || !/<head\b/i.test(html) || !/<body\b/i.test(html) || !/<\/body>\s*<\/html>\s*$/i.test(html)) fail('complete HTML document required');
if(/<(script|iframe|object|embed|form|base)\b|\son\w+\s*=|javascript\s*:/i.test(html)) fail('unsafe HTML');
if(/(?:src|href)\s*=\s*["'](?:file:|https?:\/\/(?:localhost|127\.|169\.254\.))/i.test(html)) fail('unexpected local HTML resource');
// Use the actual tool result, not an LLM copy of the final report.
return [{json:{output:html,validation_status:'passed',writer_research_calls:writer.writer_research_calls}}];
